user_prompt:
method derivative(xs: seq<int>) returns (result: seq<int>)
    requires |xs| > 0
    ensures |result| == |xs| - 1
    ensures forall i :: 0 <= i < |result| ==> result[i] == xs[i + 1] * (i + 1)
{
    var n := |xs|;
    result := [];
    var i := 0;
    while i < n - 1
        invariant 0 <= i <= n - 1
        invariant |result| == i
    {
        result := result + [xs[i + 1] * (i + 1)];
        i := i + 1;
    }
}
